            'resizeform': { sig: 'ResizeForm(Width AS INTEGER, Height AS INTEGER) AS INTEGER', desc: 'Gives the designed form this Width and Height, as dragging its edge does: the size written into its CREATE block, and the components its Anchors move written where they go.' },
            'createhandler': { sig: 'CreateHandler(Name AS STRING, Event AS STRING) AS STRING', desc: 'The SUB handling component Name\'s Event ("": its default event): the one its CREATE block names, else a new one written with the event\'s parameters and wired (one undo step). Returns the SUB\'s name; HandlerLine says where it is.' },
