            'onmove': { sig: 'OnMove(Index AS INTEGER, X AS INTEGER, Y AS INTEGER, W AS INTEGER, H AS INTEGER)', desc: 'Fires when the user moved or resized a designed component on the design surface (Index, and its new X, Y, W, H).' },
